#include <iostream>
constexpr int fact(int n) {
    return (n <= 1) ? 1 : (n * fact(n - 1));
}
int main() {
    int arr[fact(4)]; // Mảng 24 phần tử hợp lệ
    std::cout << sizeof(arr) / sizeof(int) << '\n';
}

